        int width = -5;
        int startPos = 0;

        assertThrows(IllegalArgumentException.class, () -> {
            TextHelpAppendable.indexOfWrap(text, width, startPos);
        });
    }

    @Test
    void testIndexOfWrapStartPosBeyondTextLength() {
        String text = "Sample text";
        int width = 10;
        int startPos = text.length() + 5;

        int result = TextHelpAppendable.indexOfWrap(text, width, startPos);
        assertEquals(text.length(), result);
    }

    @Test
    void testIndexOfWrapEmptyString() {
        String text = "";
        int width = 10;
        int startPos = 0;

        int result = TextHelpAppendable.indexOfWrap(text, width, startPos);
        assertEquals(0, result);
    }

    @Test
    void testIndexOfWrapWithNewLineCharacter() {
        String text = "First line\nSecond line";
        int width = 15;
        int startPos = 0;

        int result = TextHelpAppendable.indexOfWrap(text, width, startPos);
        assertEquals(10, result); // Position of \n character
    }
}
